let lockBoard,firstCard,secondCard,hasFlippedCard=!1,matches=0,attempts=0;const CARDS=document.querySelectorAll(".memory-card"),TIMER=document.getElementById("timer"),MATCHED=document.getElementById("matched"),ATTEMPTS=document.getElementById("attempts");function flipCard(){if(!lockBoard&&this!==firstCard){if(this.classList.add("flip"),!hasFlippedCard)return hasFlippedCard=!0,void(firstCard=this);secondCard=this,checkForMatch()}}function checkForMatch(){firstCard.dataset.team===secondCard.dataset.team?disableCards():unflipCards(),attempts++,ATTEMPTS.innerText=attempts}function disableCards(){firstCard.removeEventListener("click",flipCard),secondCard.removeEventListener("click",flipCard),matches++,MATCHED.innerText=matches,resetBoard()}function unflipCards(){lockBoard=!0,setTimeout((()=>{firstCard.classList.remove("flip"),secondCard.classList.remove("flip"),resetBoard()}),1e3)}function resetBoard(){hasFlippedCard=!1,lockBoard=!1,firstCard=null,secondCard=null}TIMER.innerHTML="08:52",ATTEMPTS.innerText=attempts,MATCHED.innerText=matches,CARDS.forEach((e=>{let t=Math.floor(64*Math.random());e.style.order=t})),CARDS.forEach((e=>e.addEventListener("click",flipCard)));